from pathlib import Path
import datetime
import shutil
import sys
root = Path(__file__).resolve().parent.parent
output = root/'smali/system/priv-app/SecSettings/SecSettings.apk/0010-Add-PIF-profile-settings.patch'
parts = ['From: UN1CA <unica@local>\nSubject: [PATCH] Add PIF profile and configuration submenu\n\n'
         'Generated by settings/pif/build.sh. Pixel data source and UI reference: KOWX712.\n\n']
for source in sorted(Path(sys.argv[1]).rglob('*.smali')):
    if 'io/mesalabs/unica/pif/' not in source.as_posix():
        continue  # Shared D8 annotations are supplied by the existing Quick Tiles patch.
    path = 'smali_classes4/' + source.relative_to(sys.argv[1]).as_posix()
    lines = source.read_text().splitlines(keepends=True)
    parts.append(f'diff --git a/{path} b/{path}\nnew file mode 100644\n--- /dev/null\n+++ b/{path}\n@@ -0,0 +1,{len(lines)} @@\n')
    parts.extend('+' + line for line in lines)
    parts.append('\n')
content = ''.join(parts)
if output.exists() and output.read_text() != content:
    shutil.copy2(output, str(output)+'.bak.'+datetime.datetime.now().strftime('%Y%m%d_%H%M%S_%f'))
output.write_text(content)
print(output)
